async function ddgSearch(query) {
  await tool.navigate({ tabId, url: `https://duckduckgo.com/?q=${encodeURIComponent(query)}` });
  await tool.wait_for({ tabId, condition: "selector_visible", value: "article", timeout_ms: 10000 });
  return await browserjs(tabId, () => {
    const results = [];
    document.querySelectorAll("article").forEach(art => {
      const titleEl = art.querySelector("h2 a");
      const snippetEl = art.querySelector("[data-result='snippet']") || art.querySelector("div:last-child");
      if (titleEl) {
        results.push({
          title: titleEl.textContent?.trim(),
          url: titleEl.href,
          snippet: snippetEl?.textContent?.trim()
        });
      }
    });
    return results;
  });
}

