async function searchSnippet(query) {
  await tool.navigate({ tabId, url: `https://duckduckgo.com/?q=${encodeURIComponent(query)}&kl=us-en` });
  await tool.wait_for({ tabId, condition: "selector_visible", value: "article", timeout_ms: 10000 });
  return await browserjs(tabId, () => {
    return Array.from(document.querySelectorAll("article")).map(art => {
      const h = art.querySelector("h2");
      const b = art.querySelector("[data-result='snippet']") || art.querySelector("div:last-child");
      return (h?.textContent || "") + "\n" + (b?.textContent || "");
    }).slice(0, 3).join("\n---\n");
  });
}

