const tabId = 2017691932;

const extensions = [
  { key: "camelizer", id: "ghnomdcacenbmilgjigehppbamfndblo", name: "The Camelizer" },
  { key: "honey", id: "bmnlcjabgnpnenekpadlanbbkooimhnj", name: "PayPal Honey" },
  { key: "rakuten", id: "chhjbpecpncaggjpdakmflnfcopglcmi", name: "Rakuten: Get Cash Back For Shopping" },
  { key: "capone", id: "nenlahapcbofgnanklpelkaejcehkggg", name: "Capital One Shopping" },
  { key: "retailmenot", id: "jjfblogammkiefalfpafidabbnamoknm", name: "RetailMeNot Deal Finder" },
  { key: "coupert", id: "mfidniedemcgceagapgdekdbmanojomk", name: "Coupert" },
  { key: "pricecom", id: "kmmpkhpajpecmpdmmbpjmkmcmfdahkcj", name: "Price.com" },
  { key: "karma", id: "emalgedpdlghbkikiaeocoblajamonoh", name: "Karma" },
  { key: "cnet", id: "lghjfnfolmcikomdjmoiemllfnlmmoko", name: "CNET Shopping" }
];

const results = {};

for (const ext of extensions) {
  try {
    await tool.navigate({ tabId, url: `https://extpose.com/ext/${ext.id}` });
    await tool.wait_for({ tabId, condition: "selector_visible", value: "h1", timeout_ms: 8000 });
    const data = await browserjs(tabId, () => {
      const h1 = document.querySelector("h1")?.innerText?.trim();
      const body = document.body.innerText;

      // Extract rating & reviews
      const ratingMatch = body.match(/Rating\s+([\d\.]+)\s*\(([\d,]+)\s*votes\)/i);
      const installsMatch = body.match(/Installs\s+([\d,]+)/i);
      const publisherMatch = body.match(/Publisher\s+([^\n]+)/i);

      // Extract links
      const links = Array.from(document.querySelectorAll("a")).map(a => ({ text: a.innerText.trim(), href: a.href }));
      const webPageLink = links.find(l => l.text === "Web page")?.href || null;

      return {
        h1,
        rating: ratingMatch ? ratingMatch[1] : null,
        votes: ratingMatch ? ratingMatch[2] : null,
        installs: installsMatch ? installsMatch[1] : null,
        publisher: publisherMatch ? publisherMatch[1].trim() : null,
        webPageLink,
        bodySnippet: body.slice(0, 3000)
      };
    });
    results[ext.key] = data;
  } catch (err) {
    results[ext.key] = { error: err.message };
  }
}

console.log(JSON.stringify(results, null, 2));

