  try {
    await tool.navigate({ tabId, url: item.url });
    await tool.wait_for({ tabId, condition: "selector_visible", value: "body", timeout_ms: 8000 });
    const res = await browserjs(tabId, () => ({
      title: document.title,
      textSnippet: document.body.innerText.slice(0, 1000)
    }));
    results[item.name] = res;
  } catch (e) {
    results[item.name] = { error: e.message };
  }
}

console.log(JSON.stringify(results, null, 2));

