const tabId = 2017691932;

async function ddgSearchOrganic(query) {
  await tool.navigate({ tabId, url: `https://duckduckgo.com/?q=${encodeURIComponent(query)}&kl=us-en` });
  await tool.wait_for({ tabId, condition: "selector_visible", value: "article", timeout_ms: 10000 });
  return await browserjs(tabId, () => {
    const results = [];
    document.querySelectorAll("article").forEach(art => {
      const link = art.querySelector("h2 a");
      const snippetEl = art.querySelector("[data-result='snippet']") || art.querySelector("div:last-child");
      if (link && link.href && !link.href.includes("duckduckgo.com/y.js")) {
        results.push({
          title: link.textContent?.trim(),
          url: link.href,
          snippet: snippetEl?.textContent?.trim()
        });
      }
    });
    return results;
  });
}

const queries = [
  "Keepa Amazon price tracker review site:trustpilot.com",
  "The Camelizer review site:trustpilot.com OR site:pcmag.com",
  "Rakuten cash back review site:nerdwallet.com",
  "PayPal Honey extension review site:trustpilot.com",
  "Capital One Shopping extension review site:forbes.com",
  "RetailMeNot Deal Finder review site:trustpilot.com",
  "Coupert extension review site:trustpilot.com",
  "Price.com extension review site:trustpilot.com",
  "Karma shopping assistant review site:trustpilot.com",
  "CNET Shopping extension review"
];

const sentimentLinks = {};
for (const q of queries) {
  const res = await ddgSearchOrganic(q);
  sentimentLinks[q] = res.slice(0, 2);
}

console.log(JSON.stringify(sentimentLinks, null, 2));

